import{_ as o,o as r,c as a,ag as l}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"06 职场与社会生存知识手册","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/06_职场与社会生存知识.md","filePath":"topics/tianya/handbook/06_职场与社会生存知识.md"}'),i={name:"topics/tianya/handbook/06_职场与社会生存知识.md"};function u(d,t,q,n,e,s){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="_06-职场与社会生存知识手册" tabindex="-1">06 职场与社会生存知识手册 <a class="header-anchor" href="#_06-职场与社会生存知识手册" aria-label="Permalink to &quot;06 职场与社会生存知识手册&quot;">​</a></h1><blockquote><p>知识来源：天涯神贴 47（职业规划）、53（2018裁员潮）、152（成长铁律）、178（生意场记）、125（女性秘史）、160（狐狸精修炼秘笈）、7（泰国物价）。以下每条方法均可在对应原帖找到出处。</p></blockquote><hr><h2 id="一、职业选择决策树-平台-地域-努力" tabindex="-1">一、职业选择决策树：平台＞地域＞努力 <a class="header-anchor" href="#一、职业选择决策树-平台-地域-努力" aria-label="Permalink to &quot;一、职业选择决策树：平台＞地域＞努力&quot;">​</a></h2><h3 id="_1-1-为什么是这个排序" tabindex="-1">1.1 为什么是这个排序 <a class="header-anchor" href="#_1-1-为什么是这个排序" aria-label="Permalink to &quot;1.1 为什么是这个排序&quot;">​</a></h3><ul><li><strong>努力的边际回报最低。</strong> 47号帖作者（211土木毕业）在工程局&quot;一年走掉一半人，三年剩四分之一&quot;，留下的人里拼命干的与混日子的境遇相差不大——因为工程局的苦&quot;是看不到尽头绵绵不绝的苦&quot;，这种苦不积累成稀缺能力。他后来进设计院、考注册证，收入结构才彻底改变。</li><li><strong>地域决定你接触什么。</strong> 152号帖（e路狂飙）的观点体系建立在&quot;信息鸿沟&quot;上：世家精英与普通人拉开的不是智商，是&quot;理念+习惯+方法&quot;的完整传承。大城市大公司就是把这套体系开放给你接触的地方——47号帖作者同样建议&quot;先去大城市见世面、进大公司，工作两三年后再评估哪里适合自己&quot;。</li><li><strong>平台决定你的价值上限。</strong> 一个在上升行业头部平台的人，能力会被业务量放大；一个在收缩平台的人，努力只是维持存量。2018年裁员潮（53号帖）是这个规律的残酷演示：互联网招聘职位同比-51%时，再努力的个人也只是&quot;成本&quot;。</li></ul><h3 id="_1-2-决策树的操作顺序" tabindex="-1">1.2 决策树的操作顺序 <a class="header-anchor" href="#_1-2-决策树的操作顺序" aria-label="Permalink to &quot;1.2 决策树的操作顺序&quot;">​</a></h3><ol><li><strong>先选行业（152：定位行业而非企业）。</strong> 问三个问题：这个行业十年后是在扩张还是收缩？我入行时的师父/同事是不是我要成为的人？行业寒冬时谁先被裁？（53号帖的答案：中层、可替代岗位先被裁。）</li><li><strong>再选平台。</strong> 见下节评估法。</li><li><strong>然后选地域。</strong> 47号帖的规则：年轻时大城市（用生活成本换见识与机会），工作两三年后做&quot;定居评估&quot;——&quot;如何选择都没错，都是有得有失&quot;；年长求安稳回小城市可接受。</li><li><strong>努力放最后</strong>——但不是不重要，而是在前三步错了的前提下，努力的最大产出是让你有资格重新选一次平台。</li></ol><h3 id="_1-3-怎么评估一个平台的上升空间-操作清单" tabindex="-1">1.3 怎么评估一个平台的上升空间（操作清单） <a class="header-anchor" href="#_1-3-怎么评估一个平台的上升空间-操作清单" aria-label="Permalink to &quot;1.3 怎么评估一个平台的上升空间（操作清单）&quot;">​</a></h3><p>来自47号帖的亲身对照（工程局 vs 设计院）与152号帖的&quot;陷阱岗位&quot;论：</p><ul><li><strong>看离职率与新人存活率</strong>：一年走一半的平台，说明内部晋升路径堵塞（工程局案例）。</li><li><strong>看手艺沉淀</strong>：这个岗位三五年后，你带走的是&quot;注册证/作品/客户资源&quot;，还是只有&quot;工龄&quot;？设计院带证的人跳槽议价，工地带不走东西。</li><li><strong>看岗位是否在核心链路</strong>：152号帖警告&quot;清洗老员工&quot;的空降岗九死一生（武则天用酷吏清洗旧臣，酷吏随后被清洗）；判断方法——岗位的产出是不是公司利润的直接来源，你的直属上级是不是实权派。</li><li><strong>看&quot;太顺&quot;的程度</strong>：152号帖的案例——留美博士15年不跳槽，一跳就是空降CEO，一年出局。顺利到不可思议的岗位，先怀疑是陷阱。</li><li><strong>看家庭可承受度</strong>：47号帖建议家庭&quot;经济收入不能太单一&quot;，最好有三种支柱；选平台时把&quot;如果这个平台倒了，第二支柱在哪&quot;纳入评估。</li></ul><h3 id="_1-4-利用价值-定价模型" tabindex="-1">1.4 &quot;利用价值&quot;定价模型 <a class="header-anchor" href="#_1-4-利用价值-定价模型" aria-label="Permalink to &quot;1.4 &quot;利用价值&quot;定价模型&quot;">​</a></h3><p>152号帖铁律：职场建立在利益之上，&quot;最重要的是使自己具有较好的利用价值&quot;。把它变成三个可操作的定价动作：</p><ol><li><strong>提高基础面（能力）</strong>：稀缺技能+可验证凭证（证书、作品、案例）。47号帖的注册土木工程师证是硬通货的实例。</li><li><strong>提高可见度（印象）</strong>：152号帖铁律之十九——&quot;决定你命运的是少数关键人对你的感知与评价&quot;，哪怕不客观。操作：定期用工作报告/会议/适度的&quot;不经意提及&quot;把工作细节传递给关键人；别做360度测评垫底的&quot;独行侠&quot;。作者引用的话值得记住：&quot;要想得到组织提拔，就得先进入组织视野。&quot;</li><li><strong>谈价时机</strong>：在&quot;被利用价值&quot;刚好超过平台给你的报酬时谈价（外部有offer、证书刚到手、独扛了关键项目之后），而不是在情绪不满时谈。谈不成也不裸辞（见下节）。</li></ol><hr><h2 id="二、裁员信号识别与应对清单-源自53号帖-152-47的方法" tabindex="-1">二、裁员信号识别与应对清单（源自53号帖+152/47的方法） <a class="header-anchor" href="#二、裁员信号识别与应对清单-源自53号帖-152-47的方法" aria-label="Permalink to &quot;二、裁员信号识别与应对清单（源自53号帖+152/47的方法）&quot;">​</a></h2><h3 id="_2-1-裁员潮的传导顺序-2018年样本" tabindex="-1">2.1 裁员潮的传导顺序（2018年样本） <a class="header-anchor" href="#_2-1-裁员潮的传导顺序-2018年样本" aria-label="Permalink to &quot;2.1 裁员潮的传导顺序（2018年样本）&quot;">​</a></h3><p>P2P连环爆雷（2018.6）→ 社保改由税务征收，企业用工成本升20–30%（2018.7）→ 美图、拉勾、碧桂园、魅族等&quot;人员优化&quot;（2018.8起）。智联招聘：2018Q3互联网招聘职位同比-51%，金融-46%。最受伤的两类人：背房贷车贷孩子教育费的中年人，与应届毕业生。</p><h3 id="_2-2-个体裁员信号清单-出现越多越要动" tabindex="-1">2.2 个体裁员信号清单（出现越多越要动） <a class="header-anchor" href="#_2-2-个体裁员信号清单-出现越多越要动" aria-label="Permalink to &quot;2.2 个体裁员信号清单（出现越多越要动）&quot;">​</a></h3><ul><li>行业层面：招聘职位量连续两季度下滑；行业性爆雷事件出现（53号帖：P2P爆雷是互联网裁员的先导）。</li><li>公司层面：社保/公积金缴费基数被严格化；HR突然细化考勤与绩效；&quot;人员优化&quot;&quot;降维&quot;等话术出现（53号帖名场面：&quot;10%叫人员优化……100%降维优化&quot;）；招聘冻结但裁员新闻发布。</li><li>岗位层面：你的产出可以一句话说清（＝容易被量化评估）；中层、薪资高于同岗位市场价、体力型岗位——53号帖指出这三者叠加最先被处理。</li><li>个人层面：一年以上没拿到新技能、新客户、新凭证；你的直属上级换人（152号帖：新领导清洗旧人概率高）。</li></ul><h3 id="_2-3-应对动作" tabindex="-1">2.3 应对动作 <a class="header-anchor" href="#_2-3-应对动作" aria-label="Permalink to &quot;2.3 应对动作&quot;">​</a></h3><ol><li><strong>现金流原则（不裸辞）</strong>：47号帖两度强调&quot;年龄大了不要意气用事，凡事给自己想好退路&quot;，并以其爱裸辞的妻子为反面教材。规则：永远在骑驴找马状态；离职谈成之前不动手；至少留出能覆盖6-12个月家庭固定支出的现金。</li><li><strong>家庭收入三支柱</strong>：工资收入之外，积累&quot;专业技能变现&quot;（证书挂靠、咨询、接私活）与&quot;资产性收入&quot;（理财只用闲钱，47号帖：专业是最后保障，理财只是副业）。三支柱的意义是：任何一根被裁断，家庭不塌。</li><li><strong>裁员潮中的逆向动作</strong>：53号帖数据反过来看——招聘收缩期正是低成本拿到证书、补技能、低成本试用兼职合作的窗口；别在行业底部和所有人一起挤独木桥。</li></ol><h3 id="_2-4-陷阱工作识别法-152号帖" tabindex="-1">2.4 陷阱工作识别法（152号帖） <a class="header-anchor" href="#_2-4-陷阱工作识别法-152号帖" aria-label="Permalink to &quot;2.4 陷阱工作识别法（152号帖）&quot;">​</a></h3><ul><li><strong>垃圾工作</strong>：纯消耗、无积累——发传单、无技术含量的打杂。做多了&quot;你在别人眼里也就垃圾了&quot;。</li><li><strong>陷阱工作</strong>：看起来是机会，实为替人探路或背锅。识别三问：①这活有没有技术含量？②是不是替别人探路（成果归谁）？③做砸了责任算谁的？</li><li><strong>陷阱岗位</strong>：空降岗、&quot;清洗型&quot;岗位——九死一生。识别：前任为什么走？给你这个位置的人图什么？</li><li>反面规则：<strong>别拒绝&quot;适度超能力&quot;的挑战</strong>——152号帖警告连拒三四次好机会后，机会就不再找你；但远超能力的要躲，别给自己添失败案例。</li></ul><hr><h2 id="三、生意场识人与婚姻的两套操作性结论" tabindex="-1">三、生意场识人与婚姻的两套操作性结论 <a class="header-anchor" href="#三、生意场识人与婚姻的两套操作性结论" aria-label="Permalink to &quot;三、生意场识人与婚姻的两套操作性结论&quot;">​</a></h2><h3 id="_3-1-有本事的人的行为特征-178号帖人物归纳" tabindex="-1">3.1 有本事的人的行为特征（178号帖人物归纳） <a class="header-anchor" href="#_3-1-有本事的人的行为特征-178号帖人物归纳" aria-label="Permalink to &quot;3.1 有本事的人的行为特征（178号帖人物归纳）&quot;">​</a></h3><ul><li><strong>有条理本身就是信号</strong>：女同学的哥哥&quot;吃剩的鱼骨整整齐齐摆盘里&quot;、对愚蠢问题也耐心回答、无优越感——后来此人给作者房产投资帮了大忙。观察一个人如何对待无利用价值的人与物，是最快的识人法。</li><li><strong>从小生意练出来的人</strong>：妻妹小霞&quot;一张嘴能把你领到沟里&quot;，能吃苦（冬天坐夜车进货、睡麦秸秆一个月）——嘴上功夫+吃苦耐力，是底层生意人的两项硬通货。</li><li><strong>借势而不显山露水</strong>：楼主借&quot;上面有人&quot;的模糊话术（&quot;这事XX很重视&quot;）让基层&quot;遇庙烧香&quot;——识别这类人：只制造关联，从不验证细节；与他打交道时，凡他拍胸脯的&quot;关系&quot;，一律要求落到具体人、具体时间。</li><li><strong>反面信号</strong>：楼主自省&quot;爱面子挣不了钱&quot;&quot;赚快钱、眼高手低&quot;；年轻时有钱不低调，为朋友小事挨打被拷一夜。<strong>判断生意伙伴：看他中年之后是否越做越&quot;省话&quot;</strong>——178号帖作者中年转变的标志是&quot;不再酒桌吆喝接单，报价给你，爱做不做&quot;。</li><li>贴近要学的人：&quot;赚钱一定要赚富人的钱，买房开店要离富人近&quot;——不仅是市场选择，也是信息环境选择（对应152号帖的信息鸿沟论）。</li></ul><h3 id="_3-2-婚姻的资源整合观-152号帖-→-操作结论" tabindex="-1">3.2 婚姻的资源整合观（152号帖）→ 操作结论 <a class="header-anchor" href="#_3-2-婚姻的资源整合观-152号帖-→-操作结论" aria-label="Permalink to &quot;3.2 婚姻的资源整合观（152号帖）→ 操作结论&quot;">​</a></h3><ul><li>婚姻是两家社会资源的整合（裴柏村59宰相靠联姻；卫青、诸葛亮皆因联姻上台阶）。操作结论：择偶时除了感情，明确列出双方家庭能互相补的资源短板；反对的是只看脸与情绪价值的高风险配置。</li><li>代价意识（178号帖）：&quot;娶了皮革厂老板的妹妹可少奋斗20年——门第观念害死人&quot;是楼主自省；反过来，只算计资源而不经营感情，178号帖的婚姻案例（妻子在只剩100元时说&quot;你吃吧，我喝点汤&quot;）说明：<strong>能共患难、心实、不背叛，是资源之外最值钱的一项</strong>。</li></ul><h3 id="_3-3-两性关系的操作性结论-160号帖-作者为律师" tabindex="-1">3.3 两性关系的操作性结论（160号帖，作者为律师） <a class="header-anchor" href="#_3-3-两性关系的操作性结论-160号帖-作者为律师" aria-label="Permalink to &quot;3.3 两性关系的操作性结论（160号帖，作者为律师）&quot;">​</a></h3><ul><li><strong>热恋周期论</strong>：热恋期荷尔蒙只能维持两三年；之后男性理性回归、不再迁就——&quot;婚前婚后两幅面孔&quot;是阶段差，不是人品差。操作：重大承诺（买房、辞职、生育）不要在热恋头两年做决定；对方态度变化先归因于阶段，再排查人品。</li><li><strong>承诺规则</strong>：&quot;千万不要相信男人在床上作的承诺，要听靠谱的话，等他穿上裤子。&quot;（男性理性在情绪峰值后回归；决策要在双方都冷静时谈。）</li><li><strong>痛苦阈值论</strong>：男性是&quot;默默积累负面情绪的动物&quot;，忍耐到极限会&quot;瞬间爆发，决绝翻脸&quot;（案例：公认璧人的外科大夫突然起诉离婚，放弃全部财产）。操作：别用&quot;他忍了=没事&quot;判断关系；定期主动问对方积累的不满；翻脸前的沉默期是最后的修复窗口。</li><li><strong>理性差</strong>：男性&quot;不轻易下结论，但决定后就无挽回余地&quot;；女性常在情绪中反复。操作：吵架时不说分手/离婚（说了对方可能当真受理）；情绪峰值时只表达感受，不做决定。</li><li><strong>危机处理</strong>（律师的操作流程）：决定离婚→立刻委托律师收集证据；&quot;第一次起诉法院通常不判离，过半年继续起诉&quot;；不想离就别把离婚挂嘴边，&quot;发火跟崩溃没有任何意义&quot;。</li><li><strong>幸福归因</strong>：作者断言性格对女性幸福的关联度达80%；情场最失意的不是容貌差的，是脾气差的。操作：择偶先评估对方冲突时的反应方式，而不是条件清单。</li><li><strong>处境视角</strong>（125号帖方法论）：看人先看处境——潘金莲的悲剧起点是张大户&quot;长相越丑越好、家越穷越老、人越窝囊越好、住得越近越好&quot;的恶意安排。操作：评价伴侣/合作者的&quot;人品污点&quot;前，先还原其所处的权力与经济约束，再决定修复还是止损。</li></ul><hr><h2 id="四、物价与生活成本的国际参照-7号帖完整数据" tabindex="-1">四、物价与生活成本的国际参照（7号帖完整数据） <a class="header-anchor" href="#四、物价与生活成本的国际参照-7号帖完整数据" aria-label="Permalink to &quot;四、物价与生活成本的国际参照（7号帖完整数据）&quot;">​</a></h2><h3 id="_4-1-基准" tabindex="-1">4.1 基准 <a class="header-anchor" href="#_4-1-基准" aria-label="Permalink to &quot;4.1 基准&quot;">​</a></h3><p>发帖于2011年8月，汇率1:4.7（100元≈470铢）。作者五年五次赴泰实拍。国内同期参照：2011年7月离国时排骨22元/斤，8月底回国已30元/斤。</p><h3 id="_4-2-泰国物价数据表-2011-8-泰铢" tabindex="-1">4.2 泰国物价数据表（2011.8，泰铢） <a class="header-anchor" href="#_4-2-泰国物价数据表-2011-8-泰铢" aria-label="Permalink to &quot;4.2 泰国物价数据表（2011.8，泰铢）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>价格</th><th>折人民币</th></tr></thead><tbody><tr><td>快餐（全国统一价，含机场）</td><td>30–35铢/份</td><td>6.4–7.4元</td></tr><tr><td>排骨/瘦肉</td><td>135铢/公斤</td><td>100元买3.5公斤</td></tr><tr><td>整鸡</td><td>94铢/公斤</td><td>约10元/斤</td></tr><tr><td>秋刀鱼</td><td>14铢/条</td><td>约3元</td></tr><tr><td>山竹（产地集市）</td><td>10铢/公斤</td><td>约1元/斤（进城翻倍）</td></tr><tr><td>牛奶</td><td>177铢/5升</td><td>约7.5元/升</td></tr><tr><td>超市大米</td><td>折约4元+/市斤</td><td>比国内贵；低于8元/斤的&quot;泰国米&quot;多为假货</td></tr><tr><td>汽油</td><td>约8.5元/升</td><td>但全境高速公路免费</td></tr><tr><td>曼谷—清迈700km双层VIP大巴</td><td>300–350铢</td><td>约64–74元</td></tr><tr><td>市区公交</td><td>有免费线路（蓝条车）</td><td>0元</td></tr><tr><td>海滨31平全装修公寓</td><td>51.9万铢</td><td>约11万元</td></tr><tr><td>曼谷180km外900平地独立屋</td><td>约400万铢</td><td>约85万元</td></tr><tr><td>Levis牛仔裤</td><td>约50美元/条</td><td>与国内相当</td></tr><tr><td>欧莱雅化妆品</td><td>约国内价1/3–1/4</td><td>代购热因</td></tr><tr><td>最低月工资标准</td><td>6500铢</td><td>约1350元</td></tr><tr><td>普通公司职员月薪</td><td>12000–15000铢</td><td>2550–3200元</td></tr><tr><td>大学教授月薪</td><td>10万铢</td><td>约2.1万元</td></tr></tbody></table><p><strong>福利项</strong>：月用电90度以下免费；中小学生免费牛奶；&quot;30铢看病&quot;计划（任何国立医院，含外地务工者）；寺庙及部分景点对本国人免票（外国人大皇宫门票350铢）；双向对照——泰国男性娶泰国女性也无法入籍，移民政策极紧。</p><p><strong>稳定性观察</strong>：曼谷快餐2007年25–35铢、2011年30–35铢，三年几乎未涨；同期作者在国内亲历排骨一月内22→30元/斤。&quot;物价是否稳定&quot;比&quot;物价绝对值&quot;更能说明生活成本。</p><h3 id="_4-3-这张表的对照意义-方法论" tabindex="-1">4.3 这张表的对照意义（方法论） <a class="header-anchor" href="#_4-3-这张表的对照意义-方法论" aria-label="Permalink to &quot;4.3 这张表的对照意义（方法论）&quot;">​</a></h3><ol><li><strong>四维比价法</strong>：工资水平/物价水平/福利覆盖/物价稳定性，缺一不可。单品比价会骗人——大巴便宜不代表生活便宜，房租便宜不代表可定居。</li><li><strong>可信度声明</strong>：作者自认&quot;不懂泰语，个别数字可能有出入&quot;，但全部为一手实拍、有图可查。这是跨国比较帖的范本：给数据、给汇率、给时间、承认局限。</li><li><strong>同一帖里的反面教材</strong>：评论区的骂战展示了立场如何污染事实——读这类帖子时，先看数据采集方法，再看评论区是否陷入帽子互扣。</li><li><strong>常识增量</strong>：物价稳定的国家，其快餐定价常是&quot;全国统一&quot;（连锁标准化+政府指导），这类细节比GDP更能说明普通人的日子。</li></ol>',42)])])}const _=o(i,[["render",u]]);export{g as __pageData,_ as default};
